export type CachainPluginPdas = {
  position: typeof findPositionPda;
  receipt: typeof findReceiptPda;
  contributorPosition: typeof findContributorPositionPda;
  capitalVault: typeof findCapitalVaultPda;
  incomeVault: typeof findIncomeVaultPda;
  ownershipMint: typeof findOwnershipMintPda;
  profitMint: typeof findProfitMintPda;
  extraMetas: typeof findExtraMetasPda;
  executeExtraMetas: typeof findExecuteExtraMetasPda;
  claimantPosition: typeof findClaimantPositionPda;
  eventAuthority: typeof findEventAuthorityPda;
};

export type CachainPluginRequirements = ClientWithRpc<GetAccountInfoApi & GetMultipleAccountsApi> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function cachainProgram(config: { programAddress?: Address | HasAddress } = {}) {
  return <T extends CachainPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { cachain: CachainPlugin }> => {
    return extendClient(client, {
      cachain: <CachainPlugin>{
        accounts: {
          asset: addSelfFetchFunctions(client, getAssetCodec()),
          bounty: addSelfFetchFunctions(client, getBountyCodec()),
          position: addSelfFetchFunctions(client, getPositionCodec()),
          receipt: addSelfFetchFunctions(client, getReceiptCodec()),
        },
        instructions: {
          acceptDelivery: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptDeliveryInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          cancelBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          claimDistribution: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimDistributionInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          closeFunding: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseFundingInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          contribute: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getContributeInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          createAsset: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateAssetInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          createMints: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateMintsInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          curateBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getCurateBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          execute: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getExecuteInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          freezeHolder: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getFreezeHolderInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          openBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          openPosition: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getOpenPositionInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                { programAddress: instructionConfig?.programAddress ?? config.programAddress },
              ),
            ),
          pauseBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getPauseBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          proposeBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getProposeBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          recordInflow: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecordInflowInstructionAsync(
                { ...input, payer: input.payer ?? client.payer },
                { programAddress: instructionConfig?.programAddress ?? config.programAddress },
              ),
            ),
          recordOutflow: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecordOutflowInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          rejectDelivery: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getRejectDeliveryInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          resumeBounty: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getResumeBountyInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          settleWork: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleWorkInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          submitDelivery: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getSubmitDeliveryInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
          thawHolder: (input, instructionConfig) =>
            addSelfPlanAndSendFunctions(
              client,
              getThawHolderInstructionAsync(input, {
                programAddress: instructionConfig?.programAddress ?? config.programAddress,
              }),
            ),
        },
        pdas: {
          position: (seeds, pdaConfig) =>
            findPositionPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          receipt: (seeds, pdaConfig) =>
            findReceiptPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          contributorPosition: (seeds, pdaConfig) =>
            findContributorPositionPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          capitalVault: (seeds, pdaConfig) =>
            findCapitalVaultPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          incomeVault: (seeds, pdaConfig) =>
            findIncomeVaultPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          ownershipMint: (seeds, pdaConfig) =>
            findOwnershipMintPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          profitMint: (seeds, pdaConfig) =>
            findProfitMintPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          extraMetas: (seeds, pdaConfig) =>
            findExtraMetasPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          executeExtraMetas: (seeds, pdaConfig) =>
            findExecuteExtraMetasPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          claimantPosition: (seeds, pdaConfig) =>
            findClaimantPositionPda(seeds, {
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
          eventAuthority: (pdaConfig) =>
            findEventAuthorityPda({
              programAddress: pdaConfig?.programAddress ?? config.programAddress,
            }),
        },
        identifyAccount: identifyCachainAccount,
        identifyInstruction: identifyCachainInstruction,
        parseInstruction: parseCachainInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
